/**
 * The `<arch-plan>` element on the BUILT site, in both served builds, running on the sample
 * page `/arch-plan-demo.html` (a plan by URL, `examples/studio.arch`; a plan written inline; a
 * broken plan). Plus the `/embed` page's recipe, whose version must be the real one.
 *
 * - SLIM, `/arch-plan.js` (generated by `npm run gen:arch-plan`): it imports the compiler from
 *   jsDelivr at the pinned version. Here that request is answered from this checkout's own built
 *   core (`dist/`), so the case runs offline and checks THIS tree's compiler; the URL itself is
 *   pinned by `packages/web-component/test/served-file.test.ts`.
 * - STANDALONE, `/arch-plan.standalone.js` (written by the docs build): swapped in for the slim
 *   file on the same page, with jsDelivr blocked outright.
 * - REAL jsDelivr: the one `@prod` case, unrouted. It runs only with `E2E_PROD=1` (the nightly
 *   e2e-prod job sets it; `/release-check` runs it by hand after a release), because against a
 *   local build it would test whatever jsDelivr holds, not this tree.
 *
 * The routed cases are not tagged `@prod`: they intercept requests.
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { expect, type Page, test } from "@playwright/test";
import { ROOT } from "./fixtures.js";

const VERSION: string = JSON.parse(readFileSync(join(ROOT, "package.json"), "utf8")).version;
const CDN = `https://cdn.jsdelivr.net/npm/@chanmeng666/archlang@${VERSION}/`;
const BROKEN_PRE = 'E_PARSE 3:1 Expected a value but found "}"';

/** The three elements on the demo page drew what they should. */
async function expectDemo(page: Page): Promise<void> {
  const byUrl = page.locator("#by-url .plan > svg");
  await expect(byUrl).toHaveCount(1);
  await expect(byUrl.locator("title")).toHaveText("Studio 1BR");
  const inShadow = await page.evaluate(
    () => document.querySelector("#by-url")?.shadowRoot?.querySelector("svg") instanceof SVGSVGElement,
  );
  expect(inShadow, "the drawing is in the element's shadow root").toBe(true);
  await expect(page.locator("#inline .plan > svg title")).toHaveText("Garden studio");
  await expect(page.locator("#broken pre")).toHaveText(BROKEN_PRE);
  await expect(page.locator("#broken svg")).toHaveCount(0);
}

test.describe("the <arch-plan> element", () => {
  test.beforeEach(async ({ page }) => {
    // `+esm` is the core's entry; the chunks it imports resolve beside it, so they map onto dist/.
    await page.route(`${CDN}**`, async (route) => {
      const rest = route.request().url().slice(CDN.length);
      const file = rest === "+esm" ? "index.js" : rest;
      if (!/^[\w.-]+\.js$/.test(file)) return route.abort();
      await route.fulfill({
        path: join(ROOT, "dist", file),
        contentType: "text/javascript",
        headers: { "access-control-allow-origin": "*" },
      });
    });
  });

  test("slim /arch-plan.js: imports the pinned core once and draws all three", async ({ page }) => {
    const core: string[] = [];
    page.on("request", (r) => {
      if (r.url().startsWith("https://cdn.jsdelivr.net/")) core.push(r.url());
    });
    await page.goto("/arch-plan-demo.html");
    await expectDemo(page);
    expect(
      core.filter((u) => u === `${CDN}+esm`),
      "one import of the pinned +esm URL, shared",
    ).toHaveLength(1);
  });

  test("standalone /arch-plan.standalone.js: draws all three with no CDN at all", async ({ page, request }) => {
    const res = await request.get("/arch-plan.standalone.js");
    expect(res.status()).toBe(200);
    const body = await res.text();
    expect(body).toContain('customElements.define("arch-plan"');
    expect(body, "the standalone build still imports the core from jsDelivr").not.toContain("cdn.jsdelivr.net");
    const cdn: string[] = [];
    await page.unrouteAll();
    await page.route("https://cdn.jsdelivr.net/**", (route) => {
      cdn.push(route.request().url());
      return route.abort();
    });
    await page.route("**/arch-plan.js", (route) => route.fulfill({ body, contentType: "text/javascript" }));
    await page.goto("/arch-plan-demo.html");
    await expectDemo(page);
    expect(cdn).toEqual([]);
  });

  test("/embed shows the recipe at the version this site was built from", async ({ page, request }) => {
    const pinned = `https://cdn.jsdelivr.net/npm/@chanmeng666/archlang@${VERSION}/+esm`;
    await page.goto("/embed");
    await expect(page.locator("main")).toContainText(pinned);
    await expect(page.locator("main")).not.toContainText("%ARCHLANG_VERSION%");
    const raw = await (await request.get("/embed.md")).text();
    expect(raw).toContain(pinned);
    expect(raw).not.toContain("%ARCHLANG_VERSION%");
  });
});

test.describe("the <arch-plan> element against the REAL jsDelivr", () => {
  test.skip(process.env.E2E_PROD !== "1", "set E2E_PROD=1 (nightly e2e-prod, or by hand after a release)");

  test("@prod /arch-plan-demo.html draws through the published core", async ({ page }) => {
    await page.goto("/arch-plan-demo.html");
    await expectDemo(page);
  });
});
